<script setup>
import{onMounted,reactive,ref}from'vue';import AdminLayout from'../../components/admin/AdminLayout.vue';import{adminJson}from'../../services/adminAuth';const rows=ref([]),editing=ref(null),error=ref(''),form=reactive({name_bn:'',name_en:'',description:'',sort_order:0,is_active:true});async function load(){rows.value=await adminJson('/api/admin/purposes')}function reset(){editing.value=null;Object.assign(form,{name_bn:'',name_en:'',description:'',sort_order:rows.value.length,is_active:true})}function edit(item){editing.value=item.id;Object.assign(form,{name_bn:item.name_bn,name_en:item.name_en||'',description:item.description||'',sort_order:item.sort_order,is_active:item.is_active})}async function save(){try{await adminJson(editing.value?`/api/admin/purposes/${editing.value}`:'/api/admin/purposes',{method:editing.value?'PUT':'POST',body:JSON.stringify(form)});reset();await load()}catch(e){error.value=e.message}}async function remove(item){if(!confirm(`“${item.name_bn}” মুছে ফেলবেন?`))return;try{await adminJson(`/api/admin/purposes/${item.id}`,{method:'DELETE'});await load()}catch(e){error.value=e.message}}onMounted(load)
</script>
<template><AdminLayout><div class="admin-title"><div><p>দান ব্যবস্থাপনা</p><h1>দানের উদ্দেশ্য</h1></div></div><div class="management-grid"><section class="panel"><div class="panel-head"><h2>উদ্দেশ্য তালিকা</h2></div><div class="record-list"><article v-for="item in rows" :key="item.id"><span class="order-badge">{{item.sort_order}}</span><div><b>{{item.name_bn}}</b><small>{{item.name_en||'ইংরেজি নাম নেই'}}</small></div><span class="status-pill" :class="item.is_active?'confirmed':'rejected'">{{item.is_active?'সক্রিয়':'নিষ্ক্রিয়'}}</span><button @click="edit(item)">সম্পাদনা</button><button class="danger-text" @click="remove(item)">মুছুন</button></article></div></section><section class="panel sticky-panel"><div class="panel-head"><h2>{{editing?'উদ্দেশ্য সম্পাদনা':'নতুন উদ্দেশ্য'}}</h2></div><form class="management-form" @submit.prevent="save"><label>বাংলা নাম<input v-model="form.name_bn" required></label><label>ইংরেজি নাম<input v-model="form.name_en"></label><label>বিবরণ<textarea v-model="form.description" rows="3"></textarea></label><label>ক্রম<input v-model.number="form.sort_order" type="number" min="0" required></label><label class="toggle-label"><input v-model="form.is_active" type="checkbox"> সক্রিয় রাখুন</label><p v-if="error" class="login-error">{{error}}</p><button class="admin-button">{{editing?'আপডেট করুন':'যোগ করুন'}}</button><button v-if="editing" type="button" class="secondary-button" @click="reset">বাতিল</button></form></section></div></AdminLayout></template>
